contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for property test
    function run(address newOp, address newRecipient) public payable {
        require(newOp != address(0) && newRecipient != address(0));

        // The deployer of C is its owner; this test contract is that deployer.
        // As owner we can call the two setters. Each call must NOT revert and
        // the corresponding public getter must reflect the new value.

        // Set operator
        bool revertedOp;
        try c.setOperator(newOp) {
            revertedOp = false;
        } catch {
            revertedOp = true;
        }

        // Read operator after the call
        address observedOp = c.operator();

        // Set rewards recipient
        bool revertedRec;
        try c.setRewardsRecipient(newRecipient) {
            revertedRec = false;
        } catch {
            revertedRec = true;
        }

        // Read rewardsRecipient after the call
        address observedRec = c.rewardsRecipient();

        // General rule: when owner calls these setters they must not revert and the public state variables must equal the provided values.
        // Because this test contract is the owner that deployed C, both calls should succeed.
        assert(revertedOp == false && observedOp == newOp && revertedRec == false && observedRec == newRecipient);
    }

    receive() external payable {}
}

