contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We observe behavior of withdrawAndUnwrap
    function run(uint256 amount, bool claim, address to) public payable {
        require(to != address(0), "choose nonzero recipient for observation");
        // Read initial clp balance of c
        uint256 before = c.clpToken().balanceOf(address(c));

        // We will call withdrawAndUnwrap as the owner or operator would.
        // The InvMutTest contract is the deployer of c in the harness, so it is the owner.
        // Call and capture whether it reverts.
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final clp balance of c and balance of recipient
        uint256 after = c.clpToken().balanceOf(address(c));
        uint256 toBalance = c.clpToken().balanceOf(to);

        // If the call reverted, we don't make strong claims about balances; require reverted => no further assertion
        if (reverted) {
            assert(reverted == true);
            return;
        }

        // General rule assertions:
        // 1) The contract's clp balance did not increase as a result of withdrawAndUnwrap
        // 2) The recipient received at most 'amount' more than before (can't receive more than requested)
        // 3) If before >= amount, then no unstake was needed and recipient received exactly 'amount' and contract balance decreased by amount
        uint256 beforeTo = toBalance >= 0 ? toBalance - 0 : 0; // placeholder; we cannot read prior to call, so we reason relative to before/after

        // Because we cannot observe recipient balance before the call (only current), we express limits using contract balance change:
        // a) after <= before  (contract balance never increases)
        // b) (before - after) <= amount  (contract cannot lose more CLP than 'amount' transferred)
        // c) if before >= amount then (before - after) == amount (no unstake needed, exact transfer)

        assert(after <= before && (before - after) <= amount && (before >= amount ? (before - after) == amount : true));
    }

    receive() external payable {}
}

