contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that withdrawAndUnwrap(amount, claim, to) will not make the contract's
    // reported stakedBalance() larger than the sum of (previous stakedBalance) and
    // previous token balance minus any tokens transferred out; equivalently here we
    // assert a monotonic relation: the sum of clpToken.balanceOf(c) and stakedBalance()
    // after the call is >= the same sum before the call minus the explicit amount sent
    // out to `to` (since the function may transfer `amount` to `to`). This is observable
    // via public getters only.

    // NOTE: The rule is written to avoid underflow and uses only public calls.
    function run(uint256 amount, bool claim, address to) public payable {
        require(to != address(0) ? true : true);

        // Read observable before-values
        uint256 beforeTokenBalance = c.clpToken().balanceOf(address(c));
        uint256 beforeStaked = c.stakedBalance();

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable after-values
        uint256 afterTokenBalance = c.clpToken().balanceOf(address(c));
        uint256 afterStaked = c.stakedBalance();

        // General invariant: If the call succeeded, the combined on-contract total
        // (on-chain clp token balance + reported staked balance) cannot drop by more
        // than `amount`, because the only explicit outward transfer in withdrawAndUnwrap
        // is `clpToken.safeTransfer(to, amount)` and any unstake increases token balance.
        // If the call reverted, no state changes should have occurred (so equality holds).
        if (reverted) {
            assert(beforeTokenBalance + beforeStaked == afterTokenBalance + afterStaked);
        } else {
            assert(afterTokenBalance + afterStaked + 0 <= beforeTokenBalance + beforeStaked + amount);
        }
    }

    receive() external payable {}
}

