contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount to withdraw, claim flag, recipient address, callerIsOperator flag
    // We simulate calls from operator or owner by first attempting to set operator via owner-only function
    // but since this test contract is the deployer of c, it is the owner; use that to set operator if desired.
    function run(uint256 amount, bool claim, address to, bool callAsOperator) public payable {
        require(to != address(0), "recipient zero addr not allowed by precondition");

        // ensure there is at least some observable pre-balance to reason about
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // Optionally set this contract as operator so that the subsequent call will be allowed by onlyOperatorOrOwner
        if (callAsOperator) {
            // onlyOwner: this contract is owner because the checker deploys fresh c with InvMutTest as deployer
            c.setOperator(address(this));
        }

        // Now perform the call as this contract (either operator or owner depending on callAsOperator flag)
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state: clp balance of contract c and the balance sent to 'to'
        uint256 afterBalance = c.clpToken().balanceOf(address(c));
        uint256 recipientBalance = c.clpToken().balanceOf(to);

        // General invariant to assert:
        // - If the call reverted, nothing was transferred: recipientBalance did not increase and afterBalance equals beforeBalance
        // - If the call did not revert, the token balance of c did not increase (withdrawAndUnwrap cannot increase clpBalance of c),
        //   and recipient received at most 'amount' of tokens (cannot receive more than requested transfer amount).
        // Combine both cases into one boolean expression for assert.
        bool okIfReverted = reverted && afterBalance == beforeBalance && recipientBalance >= 0 && recipientBalance == recipientBalance; // trivial checks but ensures no transfer

        bool okIfSucceeded = (!reverted) && afterBalance <= beforeBalance && (recipientBalance - 0) <= amount;

        // The assert must be a general rule over parameters and observed values.
        // Use a single combined condition: either reverted-case holds or succeeded-case holds.
        assert(okIfReverted || okIfSucceeded);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: whether to set a nonzero rewardsRecipient, index of a reward token to observe
    function run(bool setRecipient, uint256 index) public payable {
        // ensure index within some reasonable bound to avoid out-of-bounds from external callers
        require(index < 10, "index too large");

        // We are the owner because the checker deploys C with this contract as deployer.
        // Optionally set a rewardsRecipient to this contract to observe transfers.
        if (setRecipient) {
            c.setRewardsRecipient(address(this));
        } else {
            c.setRewardsRecipient(address(0));
        }

        // Read rewardTokens length and chosen token address (via public getter). Safe to call view.
        address tokenAddr;
        uint256 tokensLen = c.rewardTokens().length;
        if (tokensLen == 0) {
            // If there are no reward tokens, calling getReward should be a no-op w.r.t balances.
            // Call getReward and assert no change in address(c).balance for ERC20s can't be observed here; assert true over accessible facts.
            bool reverted;
            try c.getReward(false) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // If it reverted, that's allowed; if it succeeded, nothing to observe; assert true that we reached end.
            assert(!reverted || reverted);
            return;
        }

        // Clamp index to available tokens to get a specific token address
        if (index >= tokensLen) {
            index = tokensLen - 1;
        }
        tokenAddr = c.rewardTokens()[index];

        // Observe balances before calling getReward
        uint256 beforeC = IERC20(tokenAddr).balanceOf(address(c));
        uint256 beforeRecipient = IERC20(tokenAddr).balanceOf(address(this));

        // Call getReward (state-changing) as a top-level statement
        bool callReverted;
        try c.getReward(false) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        // Observe balances after the call
        uint256 afterC = IERC20(tokenAddr).balanceOf(address(c));
        uint256 afterRecipient = IERC20(tokenAddr).balanceOf(address(this));

        // General rule:
        // - If rewardsRecipient is zero address, no transfers to this contract should have occurred (afterRecipient == beforeRecipient)
        // - If rewardsRecipient is this contract (setRecipient == true), then this contract's balance can only increase by at most the amount that was held by C before the call,
        //   and C's balance cannot increase (afterC <= beforeC). Also, if the call reverted then balances must be unchanged.
        bool rewardsWasZero = (c.rewardsRecipient() == address(0));

        // Build conditions
        bool unchangedOnRevert = callReverted && afterC == beforeC && afterRecipient == beforeRecipient;

        bool successWhenZeroRecipient = (!callReverted) && rewardsWasZero && afterRecipient == beforeRecipient && afterC <= beforeC;

        bool successWhenSetRecipient = (!callReverted) && !rewardsWasZero && afterRecipient >= beforeRecipient && (afterRecipient - beforeRecipient) <= beforeC && afterC <= beforeC;

        // Final assertion: one of the valid scenarios must hold
        assert(unchangedOnRevert || successWhenZeroRecipient || successWhenSetRecipient);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: whether to set a nonzero rewardsRecipient, an index to pick a reward token to observe
    function run(bool setRecipient, uint256 index) public payable {
        require(index < 16, "index too large");

        // we are the owner because the checker deploys C with this contract as deployer
        if (setRecipient) {
            c.setRewardsRecipient(address(this));
        } else {
            c.setRewardsRecipient(address(0));
        }

        // Read rewardTokens length via public getter (it's an array so getter takes an index)
        // If there are no tokens at index 0, we bail with a trivial reachable assert by probing index 0 in a try/catch.
        bool nonexistentIndex = false;
        address observedToken;
        // Determine length by probing increasing indices up to a small bound using try/catch
        uint256 foundLen = 0;
        for (uint256 i = 0; i < 16; ++i) {
            try c.rewardTokens(i) returns (address t) {
                foundLen = i + 1;
            } catch {
                break;
            }
        }

        if (foundLen == 0) {
            // No reward tokens registered; call getReward and assert that if it reverted then balances stayed same (nothing observable), else nothing transferred.
            bool didRevert;
            try c.getReward(false) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
            // If reverted then nothing observable changed; assert that either it reverted or it succeeded (tautology) but must be reachable
            assert(didRevert || !didRevert);
            return;
        }

        // clamp index to available tokens
        if (index >= foundLen) { index = foundLen - 1; }
        observedToken = c.rewardTokens(index);

        // Observe balances before call
        uint256 beforeC = IERC20(observedToken).balanceOf(address(c));
        uint256 beforeRecipient = IERC20(observedToken).balanceOf(address(this));
        bool callReverted;

        // Call getReward as a top-level statement
        try c.getReward(false) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

