contract InvMutTest {
    C c;
    IERC20 clp;

    constructor(C _c) {
        c = _c;
        clp = c.clpToken();
    }

    // single public test entry
    function run(uint256 amount, bool claim, address to, address caller) public payable {
        require(caller != address(0));
        // Precondition: the test contract must be operator or owner to call withdrawAndUnwrap.
        // We can call setOperator only if we're owner; the InvMutTest is the deployer of c (per harness),
        // but to be general we try to set operator to this contract (invokable only by owner).
        // first ensure this contract is the owner by attempting transferOwnership to itself is not possible here,
        // so instead we attempt to set operator to this contract via onlyOwner function; if it reverts, we continue
        // and later call as owner alternative. We will detect whether call reverted and set a flag.

        bool setOpReverted;
        try c.setOperator(address(this)) {
            setOpReverted = false;
        } catch {
            setOpReverted = true;
        }

        // record before balance
        uint256 before = clp.balanceOf(address(c));

        // Decide who will call withdrawAndUnwrap: prefer operator (this contract) if setOperator succeeded,
        // otherwise try to call as owner by using c.owner() (we cannot change msg.sender), so we must call from this contract.
        // If not operator, the call will revert; capture revert flag.
        bool reverted;
        try c.withdrawAndUnwrap{value: 0}(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after balance
        uint256 after = clp.balanceOf(address(c));

        // General property asserted:
        // If the call reverted, then nothing guaranteed about balances here, but if it did not revert then
        // the CLP balance of c cannot have decreased by more than 'amount' (it transfers at most 'amount' out).
        // Also, after cannot be greater than before + amount (withdrawAndUnwrap should not mint CLP to c beyond amount moved in this call).
        // We assert a single condition combining these facts for all inputs.

        assert(
            reverted || ( // if not reverted, these invariants must hold
                // after >= before - amount  (avoid underflow in solidity expression by rewriting as: before <= after + amount)
                (before <= after + amount)
                // and after <= before + amount
                && (after <= before + amount)
            )
        );
    }

    receive() external payable {}
}

