contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an index for rewardTokens array to observe a particular reward token;
    // also a boolean to choose claimExtras flag when calling getReward.
    function run(uint256 rewardIndex, bool claimExtras) public payable {
        require(true);

        // Read CLP token balance of contract c before calling getReward
        address clpAddr = address(c.clpToken());
        // balanceOf is a public function on IERC20; call via interface
        uint256 clpBefore = IERC20(clpAddr).balanceOf(address(c));

        // Read rewardTokens length and chosen token address (safe: public array has getter)
        // If rewardIndex is out of bounds, the getter will revert; to avoid that, require valid index
        uint256 len = c.rewardTokens.length;
        if (len == 0) {
            // If there are no reward tokens, just call getReward and assert CLP unchanged
            bool reverted;
            try c.getReward(claimExtras) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // If call reverted, nothing else guaranteed; require it didn't revert so we reach assert
            require(!reverted);

            uint256 clpAfter = IERC20(clpAddr).balanceOf(address(c));
            assert(clpAfter == clpBefore);
            return;
        }

        // constrain rewardIndex into bounds
        rewardIndex = rewardIndex % len;
        address rewardTokenAddr = c.rewardTokens(rewardIndex);

        // Record reward token balance before
        uint256 rewardBefore = IERC20(rewardTokenAddr).balanceOf(address(c));

        // Also read current rewardsRecipient
        address recipient = c.rewardsRecipient();

        // Call getReward and capture revert
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Ensure call did not revert so the assert is reachable
        require(!reverted);

        // Read balances after
        uint256 clpAfter = IERC20(clpAddr).balanceOf(address(c));
        uint256 rewardAfter = IERC20(rewardTokenAddr).balanceOf(address(c));

        // If no rewardsRecipient set, getReward should not transfer out reward tokens, and CLP should be unchanged
        if (recipient == address(0)) {
            assert(clpAfter == clpBefore && rewardAfter == rewardBefore);
        } else {
            // If recipient is set, C will attempt to transfer any nonzero reward balances out — so after call C's balance for that reward token must be zero
            // and CLP balance should remain unchanged irrespective of recipient
            assert(clpAfter == clpBefore && (rewardBefore == 0 || rewardAfter == 0));
        }
    }

    receive() external payable {}
 }

