        // We'll try up to 4 candidate indices derived from the input.
        address tmp;
        bool ok = false;
        uint256[4] memory candidates = [rewardIndex, rewardIndex + 1, rewardIndex + 2, rewardIndex + 3];
        for (uint i = 0; i < 4; ++i) {
