        try c.rewardTokens(idx) returns (address a0) { t0 = a0; } catch { ok0 = false; }
        try c.rewardTokens(idx + 1) returns (address a1) { t1 = a1; } catch { ok1 = false; }
        try c.rewardTokens(idx + 2) returns (address a2) { t2 = a2; } catch { ok2 = false; }

        // Read balances before (treat missing or zero-address tokens as balance 0)
        uint256 b0_before = 0;
        uint256 b1_before = 0;
        uint256 b2_before = 0;
        if (ok0 && t0 != address(0)) { b0_before = IERC20(t0).balanceOf(address(c)); }
        if (ok1 && t1 != address(0)) { b1_before = IERC20(t1).balanceOf(address(c)); }
        if (ok2 && t2 != address(0)) { b2_before = IERC20(t2).balanceOf(address(c)); }

        // Make the state-changing call as its own top-level statement and record whether it reverted.
        bool callSucceeded = true;
        try c.getReward(claimExtras) { callSucceeded = true; } catch { callSucceeded = false; }

        // Read balances after
        uint256 b0_after = 0;
        uint256 b1_after = 0;
        uint256 b2_after = 0;
        if (ok0 && t0 != address(0)) { b0_after = IERC20(t0).balanceOf(address(c)); }
        if (ok1 && t1 != address(0)) { b1_after = IERC20(t1).balanceOf(address(c)); }
        if (ok2 && t2 != address(0)) { b2_after = IERC20(t2).balanceOf(address(c)); }

        // Assert the single general rule:
        // - If the call reverted: every sampled balance is unchanged.
        // - Else (succeeded) and recip != 0: no sampled balance increased (forwarded out).
        // - Else (succeeded) and recip == 0: no sampled balance decreased (kept or accumulated).
        assert(
            (!callSucceeded && b0_after == b0_before && b1_after == b1_before && b2_after == b2_before)
            || (callSucceeded && recip != address(0) && b0_after <= b0_before && b1_after <= b1_before && b2_after <= b2_before)
            || (callSucceeded && recip == address(0) && b0_after >= b0_before && b1_after >= b1_before && b2_after >= b2_before)
        );
    }

    receive() external payable {}
}

