contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving c
    function run(address operatorAddr, address to, uint256 amount, bool claim) public payable {
        require(operatorAddr != address(0), "operator not zero");
        // Set operator and ensure caller is owner to allow withdraw path: the InvMutTest deployed c so it is owner.
        // Make this contract the operator by calling setOperator (onlyOwner) so subsequent onlyOperatorOrOwner will accept this contract.
        c.setOperator(address(this));

        // Record clp balance before
        IERC20 clp = c.clpToken();
        uint256 beforeBalance = clp.balanceOf(address(c));

        // We will call withdrawAndUnwrap as operator (this contract)
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = clp.balanceOf(address(c));

        // If the call reverted, then it must be due to access control only (NotOperatorOrOwner) is impossible because we set operator to this
        // So if reverted == true then some other failure happened; assert that cannot happen (i.e., call must not revert)
        // However to be conservative we assert a general invariant about balances when the call did NOT revert:
        // If it did not revert and `to` != zero, then either beforeBalance >= amount and c transferred `amount` to `to`,
        // or beforeBalance < amount and afterBalance >= beforeBalance (i.e., withdrawAndUnwrap attempted to unstake but did not reduce net CLP held below previous balance),
        // and in both cases the sum of (c balance after) + (balance of `to` after) equals (beforeBalance + receiverBefore) except that if to==address(0) no transfer occurs.

        if (!reverted) {
            if (to != address(0)) {
                uint256 toBefore = clp.balanceOf(to);
                uint256 toAfter = clp.balanceOf(to);
                // We cannot observe intermediate transfer separately, but final relation should hold: total CLP between c and to increased by (after+toAfter)-(before+toBefore) == 0
                // Because withdrawAndUnwrap only moves CLP from c to `to` and may also unstake into c before transfer; it should not create or destroy CLP.
                // So assert conservation: beforeBalance + toBefore == afterBalance + toAfter
                assert(beforeBalance + toBefore == afterBalance + toAfter);
            } else {
                // If to is zero address then no transfer should have occurred; so c's balance should be >= beforeBalance (unstake may increase it) or equal.
                assert(afterBalance >= beforeBalance);
            }
        } else {
            // If reverted, require that operator check failed would be false (we set operator to this), so revert indicates no CLP lost: balances unchanged
            // In worst case, assert that c's balance did not decrease (conservative)
            assert(afterBalance >= beforeBalance);
        }
    }

    receive() external payable {}
}

