contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount to withdraw, whether to claim, recipient, and a bool indicating whether the call should be made as operator (true) or as arbitrary caller (false)
    function run(uint256 amount, bool claim, address to, bool callAsOperator) public payable {
        require(to != address(0) || to == address(0)); // no constraint; keep symbolic

        // Record pre-state observable: clpToken balance of c and contract's clpToken balance (via showPositions)
        uint256 beforeStaked = c.stakedBalance();
        uint256 beforeEarned = c.earned();
        uint256 cBalanceBefore = IERC20(address(c.clpToken())).balanceOf(address(c));

        // Decide caller: if callAsOperator true, call through c.operator() must be equal to this contract to succeed.
        // We cannot change c.operator() except via onlyOwner, and this test deployer is owner; set operator to this contract if desired.
        // Attempt to set operator to this contract (onlyOwner). This is a state-changing call and must be top-level.
        // Wrap in try/catch to observe revert without aborting.
        bool setOpReverted;
        try c.setOperator(address(this)) {
            setOpReverted = false;
        } catch {
            setOpReverted = true;
        }

        // If we failed to set operator, we will attempt to call withdrawAndUnwrap as regular caller (should revert unless owner/operator)
        bool withdrewReverted;
        if (callAsOperator && !setOpReverted) {
            // call should be from this contract which is now operator
            try c.withdrawAndUnwrap(amount, claim, to) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            // call from this contract but not operator (either because callAsOperator==false or setOperator failed)
            try c.withdrawAndUnwrap(amount, claim, to) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        // Observables after attempt
        uint256 afterStaked = c.stakedBalance();
        uint256 afterEarned = c.earned();
        uint256 cBalanceAfter = IERC20(address(c.clpToken())).balanceOf(address(c));

        // General rule to assert:
        // 1) If the withdraw call reverted, then nothing guaranteed about balances here beyond that it reverted.
        // 2) If the withdraw call did NOT revert, then the contract's CLP token balance (IERC20 balanceOf(c)) cannot have increased (withdraw and unwrap should not increase token holdings),
        //    and the amount transferred out to `to` cannot exceed the requested amount. We cannot directly observe transfer amount, but we can observe decrease in c's CLP balance is at most `amount`.
        // We assert: if not reverted then cBalanceAfter <= cBalanceBefore and (cBalanceBefore - cBalanceAfter) <= amount.

        // compute delta safely: since unsigned, ensure non-negative by checking <= before
        bool condition;
        if (withdrewReverted) {
            // if reverted, we accept that (no stronger invariant), so assert true to allow prover to find executions reaching here
            condition = true;
        } else {
            // not reverted: cBalanceAfter <= cBalanceBefore and cBalanceBefore - cBalanceAfter <= amount
            bool nonIncrease = cBalanceAfter <= cBalanceBefore;
            bool decreasedAtMost = (cBalanceBefore - cBalanceAfter) <= amount;
            condition = nonIncrease && decreasedAtMost;
        }

        assert(condition);
    }

    // allow receiving ETH if needed by called functions (none here uses ETH, but provided for completeness)
    receive() external payable {}
}

