        // The deployed c's operator and owner are set at construction; this test
        // contract is the deployer of c per harness description, so msg.sender here
        // is this contract and it's also the owner. We invoke the function.
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe balance after the call
        uint256 after = clp.balanceOf(address(c));

