        // (before - after) is at most `amount`. If it reverted, nothing guaranteed
        // about balances so we only assert the rule when not reverted.
        // Express: reverted => true OR (before >= after && before - after <= amount)
        // Avoid underflow in subtraction by using comparisons only.

        assert(reverted || (after <= before && (before - after) <= amount));
    }

    receive() external payable {}
}

