        // Determine whether this test contract is the operator or owner via public getters
        bool isOperator = (c.operator() == address(this));
        bool isOwner = (c.owner() == address(this));

        // General rule (single assert): If caller (this contract) is neither operator nor owner, the call must revert.
        // If caller is operator or owner and the call did not revert, the CLP balance of c must not have increased.
        assert(
            ( (!isOperator && !isOwner) ? reverted : (!reverted ? afterClpBalance <= beforeClpBalance : true) )
        );
    }

    receive() external payable {}
}
